INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a01','A cidade também se lê pelas calçadas','cidade-se-le-pelas-calcadas','Pisos, sombras e pequenos desvios mostram quem consegue circular com conforto — e quem precisa pedir licença ao caminho.','["Uma calçada parece simples até o momento em que deixa de funcionar. Um degrau sem aviso, uma árvore que interrompe a passagem ou um carro estacionado sobre o piso transformam poucos metros em uma negociação diária.","Olhar para o chão é também observar decisões públicas. A largura do passeio, a continuidade do piso e o lugar reservado às árvores contam como a cidade distribui conforto, sombra e autonomia.","Quando moradores descrevem o caminho que fazem, aparecem detalhes que um mapa não registra: a esquina onde a travessia demora, o trecho que alaga e a sombra que torna possível esperar o ônibus. São pistas para pensar uma cidade feita para as pessoas."]','cidade','pedro-alves','/images/casas-brasileiras.png','Casas coloridas, uma árvore de rua e uma bicicleta diante de um passeio de pedra','published',1,1,'2026-11-24T12:00:00.000Z','2026-11-24T12:00:00.000Z','A cidade também se lê pelas calçadas | Pé de Prosa','Pisos, sombras e pequenos desvios mostram quem consegue circular com conforto — e quem precisa pedir licença ao caminho.');
