INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a02','O caderno de receitas que guarda uma família inteira','caderno-receitas-guarda-familia','Entre medidas aproximadas e manchas de café, um caderno doméstico registra escolhas, ausências e mudanças de uma geração para outra.','["A receita escrita à mão quase nunca começa pela quantidade. Primeiro vem uma lembrança: o almoço de domingo, a vizinha que ensinou o ponto ou a ocasião em que alguém resolveu acrescentar um ingrediente.","Esses cadernos mudam junto com a casa. Uma página recebe uma nota na margem, outra guarda a adaptação feita quando um ingrediente ficou caro ou difícil de encontrar.","Ler uma receita antiga não é apenas repetir um prato. É perceber como as pessoas ajustam a tradição às condições de cada tempo — e como certos gestos seguem passando de mão em mão."]','cotidiano','joana-melo','/images/caderno-receitas.png','Caderno aberto com anotações culinárias, colher de madeira e pequenos frutos','published',1,1,'2026-11-23T12:00:00.000Z','2026-11-23T12:00:00.000Z','O caderno de receitas que guarda uma família inteira | Pé de Prosa','Entre medidas aproximadas e manchas de café, um caderno doméstico registra escolhas, ausências e mudanças de uma geração para outra.');
