INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a03','Quando a praça vira sala de estar','quando-praca-vira-sala-de-estar','Bancos, sombra e programação ajudam a transformar um espaço de passagem em lugar de encontro cotidiano.','["No fim da tarde, a praça ganha outros usos. Quem volta do trabalho encurta o caminho, crianças inventam um jogo e vizinhos param para conversar antes de seguir para casa.","A diferença entre atravessar e permanecer está em escolhas concretas: sombra, bancos, iluminação, manutenção e atividades que não tratem o espaço público como cenário vazio.","Quando a praça acolhe usos diversos, ela passa a fazer parte da rotina. O encontro deixa de depender de um evento especial e encontra espaço na vida comum."]','cidade','caio-nunes','/images/casas-brasileiras.png','Banco de praça sob uma árvore com livros e folhas ao redor','published',1,1,'2026-11-22T12:00:00.000Z','2026-11-22T12:00:00.000Z','Quando a praça vira sala de estar | Pé de Prosa','Bancos, sombra e programação ajudam a transformar um espaço de passagem em lugar de encontro cotidiano.');
