INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a04','O que uma feira livre ensina sobre economia local','feira-livre-economia-local','A feira é mercado, rede de confiança e termômetro dos hábitos de um bairro — tudo ao mesmo tempo.','["Na feira, os preços mudam de banca para banca e a conversa faz parte da compra. O freguês pergunta de onde veio a fruta; quem vende percebe o que está faltando antes de a lista terminar.","Essa proximidade sustenta uma economia de escala pequena, mas cheia de relações. Produtores, transportadores, comerciantes e compradores dividem o mesmo espaço e ajustam suas decisões ao movimento do dia.","Observar uma feira ajuda a entender que economia não é apenas número agregado. Também é confiança, acesso, sazonalidade e a possibilidade de manter renda circulando perto de casa."]','cotidiano','joana-melo','/images/caderno-receitas.png','Banca de feira com frutas, balança e sacolas reutilizáveis','published',1,1,'2026-11-21T12:00:00.000Z','2026-11-21T12:00:00.000Z','O que uma feira livre ensina sobre economia local | Pé de Prosa','A feira é mercado, rede de confiança e termômetro dos hábitos de um bairro — tudo ao mesmo tempo.');
