INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a05','A biblioteca de bairro que começou com uma estante','biblioteca-bairro-uma-estante','Uma iniciativa de leitura cresce quando encontra espaço, rotina e gente disposta a cuidar do acervo em conjunto.','["A primeira estante veio de uma doação. Depois chegaram livros usados, uma cadeira emprestada e uma caixa para anotar o que cada pessoa queria ler.","O acervo cresceu, mas o que manteve a iniciativa aberta foi a rotina. Alguém organizava os títulos; outra pessoa preparava uma roda de leitura; moradores ajudavam a divulgar os horários.","Uma biblioteca comunitária não precisa começar grande para ser importante. Ela cria um endereço para a curiosidade e um motivo para pessoas diferentes ocuparem o mesmo espaço."]','cultura','ana-luz','/images/livros-leitura.png','Pilha de livros ilustrados e uma pequena planta em vaso','published',0,1,'2026-11-20T12:00:00.000Z','2026-11-20T12:00:00.000Z','A biblioteca de bairro que começou com uma estante | Pé de Prosa','Uma iniciativa de leitura cresce quando encontra espaço, rotina e gente disposta a cuidar do acervo em conjunto.');
