INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a07','O trabalho invisível por trás de uma entrega rápida','trabalho-invisivel-entrega-rapida','A promessa de poucos minutos depende de uma cadeia de decisões, deslocamentos e tarefas que raramente aparecem na tela.','["O aplicativo mostra uma rota simples. Do outro lado da tela, alguém calcula distância, clima, trânsito, segurança e o tempo disponível para cumprir a próxima etapa.","A velocidade percebida pelo consumidor resulta de uma organização complexa. Algoritmos distribuem pedidos, estabelecimentos preparam produtos e trabalhadores ajustam o trajeto a condições que mudam a cada minuto.","Falar sobre conveniência sem falar sobre trabalho deixa metade da história de fora. Perguntar quem assume os atrasos e os riscos ajuda a avaliar o que uma promessa de rapidez realmente custa."]','trabalho','lucas-reis','/images/trabalho-entrega.png','Bicicleta de entregas encostada a uma parede com capacete e mochila','published',0,1,'2026-11-18T12:00:00.000Z','2026-11-18T12:00:00.000Z','O trabalho invisível por trás de uma entrega rápida | Pé de Prosa','A promessa de poucos minutos depende de uma cadeia de decisões, deslocamentos e tarefas que raramente aparecem na tela.');
