INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a08','Festa de rua é também um jeito de contar a história','festa-de-rua-conta-historia','Música, comida e cortejo mantêm vivas memórias que nem sempre encontram lugar nos arquivos oficiais.','["Uma festa popular reúne lembranças que não cabem em uma placa. Elas aparecem nas músicas repetidas, nos nomes de quem ensinou o cortejo e nos objetos guardados para o próximo ano.","A preparação também é parte da história. Costureiras, músicos, cozinheiras, vizinhos e comerciantes organizam um trabalho coletivo que transforma uma rua comum por algumas horas.","Quando uma celebração continua, ela não preserva o passado intacto. Cada geração acrescenta gestos e significados, mantendo a tradição aberta à vida de quem participa."]','cultura','maira-costa','/images/livros-leitura.png','Bandeirolas coloridas e instrumentos de percussão em uma rua enfeitada','published',0,1,'2026-11-17T12:00:00.000Z','2026-11-17T12:00:00.000Z','Festa de rua é também um jeito de contar a história | Pé de Prosa','Música, comida e cortejo mantêm vivas memórias que nem sempre encontram lugar nos arquivos oficiais.');
