INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a09','A sombra das árvores muda o caminho de quem anda','sombra-arvores-muda-caminho','Em dias quentes, a arborização deixa de ser detalhe paisagístico e passa a influenciar como as pessoas se deslocam.','["Quem caminha em uma rua quente aprende rápido onde existe sombra. O trajeto mais curto pode deixar de ser o mais possível quando o sol ocupa toda a calçada.","Árvores bem cuidadas ajudam a reduzir a exposição ao calor e tornam espaços públicos mais convidativos. Para isso, precisam de solo, espaço para as raízes e manutenção regular.","Planejar sombra é planejar deslocamento, saúde e convivência. A copa que protege uma pessoa esperando o ônibus também muda a forma como a rua pode ser usada."]','natureza','davi-moraes','/images/brand-jabuticaba.png','Copa de árvore projetando sombra sobre um caminho urbano','published',0,1,'2026-11-16T12:00:00.000Z','2026-11-16T12:00:00.000Z','A sombra das árvores muda o caminho de quem anda | Pé de Prosa','Em dias quentes, a arborização deixa de ser detalhe paisagístico e passa a influenciar como as pessoas se deslocam.');
