INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a11','Por que guardar fotografias em caixas de sapato','guardar-fotografias-caixas-sapato','O arquivo familiar nasce de escolhas simples: o que identificar, quem reconhecer e como contar a história de uma imagem.','["Uma fotografia sem data ainda pode ser reconhecida pelo lugar, pela roupa ou por alguém que se lembra da ocasião. A legenda muitas vezes começa com uma pergunta feita durante uma visita.","Organizar imagens é construir uma conversa entre gerações. Nomear as pessoas e registrar o que se sabe ajuda a preservar detalhes que a memória, sozinha, pode deixar escapar.","A caixa não precisa virar um arquivo perfeito. Um pouco de cuidado e contexto já transforma um conjunto de imagens em uma coleção que outras pessoas conseguem ler."]','cultura','ana-luz','/images/livros-leitura.png','Fotografias antigas, envelopes e uma caixa de papel sobre a mesa','published',0,1,'2026-11-14T12:00:00.000Z','2026-11-14T12:00:00.000Z','Por que guardar fotografias em caixas de sapato | Pé de Prosa','O arquivo familiar nasce de escolhas simples: o que identificar, quem reconhecer e como contar a história de uma imagem.');
INSERT INTO article_tags (article_id,tag_id) VALUES ('a11','memoria');
