INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a14','Quando a chuva forte encontra a rua impermeável','chuva-forte-rua-impermeavel','O excesso de água não aparece de repente: ele se relaciona com o solo coberto, a drenagem e a ocupação de áreas baixas.','["Quando a chuva chega, cada superfície responde de um jeito. A terra absorve parte da água; o asfalto acelera seu caminho até o ponto mais baixo.","Drenagem é uma rede de decisões: galerias, áreas permeáveis, limpeza de canais e respeito ao curso natural da água. Se um trecho falha, o problema aparece em outro lugar.","Conversar sobre enchentes exige olhar além do dia da chuva. O desenho da rua e as escolhas de ocupação feitas ao longo do tempo participam do risco que os moradores enfrentam."]','natureza','davi-moraes','/images/brand-jabuticaba.png','Nuvem de chuva sobre casas e uma rua com áreas verdes','review',0,1,NULL,'2026-11-11T12:00:00.000Z','Quando a chuva forte encontra a rua impermeável | Pé de Prosa','O excesso de água não aparece de repente: ele se relaciona com o solo coberto, a drenagem e a ocupação de áreas baixas.');
