INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a16','O banco da praça como projeto de convivência','banco-praca-projeto-convivencia','Um assento público parece pequeno, mas sua posição pode aproximar pessoas ou deixar o espaço sem uso.','["Bancos de praça são usados por motivos diferentes: descansar, esperar alguém, observar o movimento ou conversar com quem chegou junto.","O lugar onde ficam muda a experiência. Um banco exposto ao sol, afastado do caminho ou sem manutenção tende a ser ignorado, mesmo quando existe demanda por um lugar para sentar.","Projetar mobiliário urbano pede atenção a esses usos. A convivência começa em detalhes que permitem permanecer sem precisar consumir nada."]','cidade','caio-nunes','/images/casas-brasileiras.png','Banco de madeira sob árvore ao lado de um caminho de praça','approved',0,1,NULL,'2026-11-09T12:00:00.000Z','O banco da praça como projeto de convivência | Pé de Prosa','Um assento público parece pequeno, mas sua posição pode aproximar pessoas ou deixar o espaço sem uso.');
