INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a21','Uma varanda muda a conversa com a rua','varanda-muda-conversa-com-rua','Entre o espaço privado e a calçada, a varanda cria uma zona de observação, descanso e contato com a vizinhança.','["Há casas em que a varanda funciona como sala aberta. Uma cadeira voltada para a rua, uma planta que recebe água no fim da tarde e a possibilidade de cumprimentar quem passa transformam poucos metros em um lugar de permanência.","A arquitetura organiza essa relação sem determinar o que vai acontecer. Altura, sombra e visibilidade influenciam se alguém se sente à vontade para ficar, conversar ou apenas acompanhar o movimento da calçada.","Pensar a moradia a partir de seus limites ajuda a entender que privacidade e convivência não são opostos absolutos. Há espaços intermediários que tornam possível estar perto sem deixar de estar em casa."]','cidade','pedro-alves','/images/casas-brasileiras.png','Ilustração editorial sobre cidade','published',0,1,'2026-11-23T12:00:00.000Z','2026-11-23T12:00:00.000Z','Uma varanda muda a conversa com a rua | Pé de Prosa','Entre o espaço privado e a calçada, a varanda cria uma zona de observação, descanso e contato com a vizinhança.');
