INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a22','O caminho mais longo quando falta sombra','caminho-mais-longo-falta-sombra','Em dias quentes, a escolha do trajeto envolve mais do que distância: entra na conta o conforto de conseguir continuar andando.','["No mapa, duas rotas podem parecer equivalentes. Na rua, a diferença aparece quando uma delas oferece árvores, marquises e lugares para parar, enquanto a outra atravessa um trecho exposto ao sol.","A sombra é distribuída de maneira desigual. Ela depende da vegetação, do desenho das quadras e dos espaços onde as pessoas podem esperar sem atrapalhar a circulação. Para quem caminha devagar, cada pausa altera o alcance do trajeto.","Uma cidade caminhável não se mede apenas pela existência de calçadas. Também importa se elas oferecem condições para que pessoas com idades e ritmos diferentes consigam usá-las durante o dia."]','natureza','davi-moraes','/images/brand-jabuticaba.png','Ilustração editorial sobre natureza','published',0,1,'2026-11-22T12:00:00.000Z','2026-11-22T12:00:00.000Z','O caminho mais longo quando falta sombra | Pé de Prosa','Em dias quentes, a escolha do trajeto envolve mais do que distância: entra na conta o conforto de conseguir continuar andando.');
