INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a27','A louça herdada que continua em uso','louca-herdada-continua-em-uso','Pratos guardados por décadas atravessam mudanças de casa e ganham novos sentidos na rotina de quem os recebe.','["Algumas peças chegam à casa nova embrulhadas em jornal e acompanhadas por uma história curta. A pessoa que entrega lembra onde comprou; quem recebe escolhe um lugar no armário e decide quando usá-las.","O valor desses objetos não depende de serem raros. Ele aparece na repetição: um prato que sai do armário nos dias comuns, uma travessa que reúne a família e uma xícara cuja lasca já faz parte do desenho.","Manter uma peça em uso evita que a memória fique limitada à vitrine. Cada refeição acrescenta outra camada à história que veio junto com o objeto."]','cotidiano','joana-melo','/images/caderno-receitas.png','Ilustração editorial sobre cotidiano','published',0,1,'2026-11-17T12:00:00.000Z','2026-11-17T12:00:00.000Z','A louça herdada que continua em uso | Pé de Prosa','Pratos guardados por décadas atravessam mudanças de casa e ganham novos sentidos na rotina de quem os recebe.');
