INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a28','O bilhete deixado dentro de um livro','bilhete-deixado-dentro-livro','Papéis esquecidos entre páginas podem transformar a leitura em um encontro com a rotina de outra pessoa.','["Um recibo antigo aparece entre dois capítulos. No verso, há uma lista incompleta; em outra página, alguém sublinhou uma frase e escreveu uma pergunta curta. A leitura passa a dividir espaço com rastros de quem segurou aquele livro antes.","Esses sinais não explicam tudo sobre a pessoa que os deixou. Ainda assim, aproximam a leitura de uma experiência concreta: alguém leu em um intervalo, levou o livro consigo e talvez tenha pensado em outra coisa enquanto virava a página.","O bilhete funciona como uma pequena margem compartilhada. Ele lembra que os livros circulam, mudam de mão e continuam acumulando sentidos fora do texto impresso."]','cultura','ana-luz','/images/livros-leitura.png','Ilustração editorial sobre cultura','published',0,1,'2026-11-16T12:00:00.000Z','2026-11-16T12:00:00.000Z','O bilhete deixado dentro de um livro | Pé de Prosa','Papéis esquecidos entre páginas podem transformar a leitura em um encontro com a rotina de outra pessoa.');
