INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a30','A roda de conversa que começa com uma pergunta','roda-conversa-comeca-pergunta','Uma pergunta aberta pode mudar o tom de um encontro e permitir que experiências diferentes encontrem espaço.','["Em uma roda, a primeira pergunta define mais do que o assunto. Ela sugere se o encontro será uma disputa por respostas rápidas ou uma oportunidade de ouvir como cada pessoa chegou até ali.","Uma boa conversa precisa de tempo, regras simples e espaço para que alguém mude de ideia sem perder a palavra. Isso não elimina divergências; ajuda a tornar visíveis os motivos que as sustentam.","Perguntar antes de concluir é um gesto pequeno, mas pode alterar a qualidade de uma discussão. A resposta talvez não resolva o problema, porém oferece um ponto de partida mais honesto para continuar."]','ideias','bia-sampaio','/images/livros-leitura.png','Ilustração editorial sobre ideias','published',0,1,'2026-11-14T12:00:00.000Z','2026-11-14T12:00:00.000Z','A roda de conversa que começa com uma pergunta | Pé de Prosa','Uma pergunta aberta pode mudar o tom de um encontro e permitir que experiências diferentes encontrem espaço.');
