INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a32','O que uma fila revela sobre o serviço público','fila-revela-servico-publico','Esperar por atendimento também é uma experiência de organização, informação e respeito ao tempo de quem precisa.','["Uma fila tem regras visíveis e outras que as pessoas descobrem perguntando. Onde retirar uma senha, quanto tempo esperar e quais documentos levar são informações que mudam a experiência antes mesmo do atendimento começar.","O tempo de espera não depende apenas do número de pessoas. Também importa se há orientação clara, acessibilidade, assentos e uma forma de avisar quando a ordem muda.","Observar uma fila ajuda a perceber que a qualidade de um serviço público inclui o percurso inteiro. A organização do atendimento pode diminuir a incerteza e tratar com mais cuidado quem precisa resolver algo importante."]','ideias','bia-sampaio','/images/livros-leitura.png','Ilustração editorial sobre ideias','published',0,1,'2026-11-12T12:00:00.000Z','2026-11-12T12:00:00.000Z','O que uma fila revela sobre o serviço público | Pé de Prosa','Esperar por atendimento também é uma experiência de organização, informação e respeito ao tempo de quem precisa.');
