INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a34','A conversa que acompanha uma compra usada','conversa-acompanha-compra-usada','Negociar um objeto de segunda mão envolve preço, confiança e uma breve história sobre como ele chegou até ali.','["Uma bicicleta usada não aparece apenas como fotografia e preço. A conversa costuma incluir há quanto tempo está parada, qual peça foi trocada e por que o dono decidiu colocá-la à venda.","A negociação depende de informações que a plataforma não organiza sozinha. Perguntas, imagens adicionais e a possibilidade de conferir o objeto ajudam as duas partes a combinar expectativas.","Mercados de segunda mão prolongam o uso das coisas, mas também dependem de confiança e de condições seguras para a troca. A experiência começa bem antes de o objeto chegar à nova casa."]','trabalho','lucas-reis','/images/trabalho-entrega.png','Ilustração editorial sobre trabalho','published',0,1,'2026-11-10T12:00:00.000Z','2026-11-10T12:00:00.000Z','A conversa que acompanha uma compra usada | Pé de Prosa','Negociar um objeto de segunda mão envolve preço, confiança e uma breve história sobre como ele chegou até ali.');
