INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a41','O passeio sem destino que ensina a conhecer o bairro','passeio-sem-destino-conhecer-bairro','Andar sem uma lista de compromissos permite notar fachadas, usos e lugares que passam despercebidos na pressa.','["Em um passeio sem destino, a esquina deixa de ser apenas um ponto de passagem. Uma porta aberta, uma árvore carregada ou um banco usado por muitas pessoas pode mudar a direção da caminhada.","Conhecer um bairro também exige observar seus ritmos. Há ruas que ficam movimentadas em determinados horários e espaços que só revelam sua função quando a vizinhança os ocupa.","A caminhada não substitui mapas nem resolve problemas de mobilidade. Ela oferece, porém, uma forma de atenção que ajuda a perceber como o lugar funciona para quem vive nele."]','cidade','caio-nunes','/images/casas-brasileiras.png','Ilustração editorial sobre cidade','published',0,1,'2026-11-03T12:00:00.000Z','2026-11-03T12:00:00.000Z','O passeio sem destino que ensina a conhecer o bairro | Pé de Prosa','Andar sem uma lista de compromissos permite notar fachadas, usos e lugares que passam despercebidos na pressa.');
