INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a42','A receita anotada de ouvido','receita-anotada-de-ouvido','Quando alguém cozinha seguindo instruções faladas, medidas e tempos ganham o sentido de quem conhece a própria panela.','["A instrução começa com um punhado e termina quando a mistura chega ao ponto. Quem aprende tenta transformar a fala em anotação, mas percebe que a panela, o fogo e os ingredientes também participam da medida.","Receitas transmitidas de ouvido carregam referências que fazem sentido dentro de uma cozinha: a colher de sempre, o tempo de dourar e o cheiro que indica a hora de mexer.","Registrar essas pistas não significa substituir a experiência de quem ensinou. O caderno pode guardar as palavras e, ao mesmo tempo, deixar espaço para que a próxima pessoa encontre seu próprio jeito de cozinhar."]','cotidiano','joana-melo','/images/caderno-receitas.png','Ilustração editorial sobre cotidiano','published',0,1,'2026-11-02T12:00:00.000Z','2026-11-02T12:00:00.000Z','A receita anotada de ouvido | Pé de Prosa','Quando alguém cozinha seguindo instruções faladas, medidas e tempos ganham o sentido de quem conhece a própria panela.');
